import{_ as a,o as n,c as s,a2 as e}from"./chunks/framework.YT-FC_Xx.js";const h=JSON.parse('{"title":"基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":1792456433000}'),r={name:"guide/concepts.md"};function d(o,t,l,i,p,g){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><p>FLYX 由一个 <strong>面板</strong> 和装在各台服务器上的 <strong>节点 agent</strong> 组成：面板负责配置和展示，agent 负责在服务器上执行。先弄清下面几个词，后面的文档会好读很多。</p><h2 id="整体结构" tabindex="-1">整体结构 <a class="header-anchor" href="#整体结构" aria-label="Permalink to &quot;整体结构&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 ──► 中转机（前置 / IX）──► 落地机（运行 Xray / sing-box / Snell）──► 网站</span></span>
<span class="line"><span>             ▲                        ▲</span></span>
<span class="line"><span>             └──── 节点 agent ─────────┘</span></span>
<span class="line"><span>                        ▲</span></span>
<span class="line"><span>                     面板（Web 界面 + 后端）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>名词</th><th>是什么</th><th>在面板哪里</th></tr></thead><tbody><tr><td>面板</td><td>Web 界面和后端，用 Docker 部署在一台服务器上</td><td>—</td></tr><tr><td>节点</td><td>装了 agent、连上面板的服务器，可以当落地，也可以当中转</td><td><strong>节点</strong> 页</td></tr><tr><td>内核</td><td>落地机上真正跑代理协议的程序：Xray、sing-box 或 Snell</td><td><strong>落地 → 内核</strong></td></tr><tr><td>入站</td><td>内核上的一个代理服务（协议 + 端口 + 凭据），客户端连的就是它</td><td><strong>落地 → 入站</strong></td></tr><tr><td>导入的节点</td><td>不是面板搭的现成节点（脚本搭的、机场的），只用来接中转、进订阅</td><td><strong>落地 → 导入</strong></td></tr><tr><td>隧道</td><td>从入口节点到出口节点的转发线路</td><td><strong>中转 → 隧道</strong></td></tr><tr><td>中转线路</td><td>把某条隧道接到某个落地上，客户端先连中转再到落地</td><td><strong>中转 → 线路</strong></td></tr><tr><td>转发规则</td><td>传统的端口转发：入口端口收到的流量转到目标地址</td><td><strong>规则</strong> 页</td></tr><tr><td>订阅</td><td>一个链接，包含选中的落地和它们的中转线路，客户端导入即用</td><td><strong>订阅</strong> 页</td></tr></tbody></table><h2 id="落地和中转" tabindex="-1">落地和中转 <a class="header-anchor" href="#落地和中转" aria-label="Permalink to &quot;落地和中转&quot;">​</a></h2><ul><li><strong>落地</strong>：客户端最终连到的节点，网站看到的是落地的 IP。可以在自己的服务器上搭（装内核、建入站），也可以导入现成的节点</li><li><strong>中转</strong>：客户端和落地之间的跳板，用来改善线路（比如国内前置 → IX → 海外落地），本身不跑代理协议，只转发流量</li></ul><p>一台服务器可以同时当落地和中转。</p><h2 id="一条线路怎么搭起来" tabindex="-1">一条线路怎么搭起来 <a class="header-anchor" href="#一条线路怎么搭起来" aria-label="Permalink to &quot;一条线路怎么搭起来&quot;">​</a></h2><ol><li><a href="./install">安装面板</a>，在 <strong>设置</strong> 里填好“面板后端地址”</li><li><a href="./agent">安装节点</a>：在落地机和中转机上运行面板生成的安装命令</li><li><a href="./nodes">搭建落地</a>：给落地机装内核、建入站</li><li><a href="./relay">对接中转</a>（可选）：建隧道，把它接到落地上</li><li><a href="./subscription">订阅</a>：把落地和中转线路一起导入客户端</li></ol><p>照着做一遍见 <a href="./getting-started">快速上手</a>。</p>`,11)])])}const u=a(r,[["render",d]]);export{h as __pageData,u as default};
